// components/Table.tsx

import React, { useMemo, useState } from "react";
import { User } from "../pages/Users";

interface Column {
  label: string;
  key: keyof User;
}

interface Props {
  data: User[];
  columns: Column[];
  onSort: (key: keyof User) => void;
  sortConfig?: {
    key: keyof User;
    direction: "asc" | "desc";
  } | null;
}

const ROWS_PER_PAGE = 10;

export const UserTable: React.FC<Props> = ({
  data,
  columns,
  onSort,
  sortConfig,
}) => {
  const [currentPage, setCurrentPage] = useState(1);

  const totalPages = Math.ceil(
    data.length / ROWS_PER_PAGE
  );

  const paginatedData = useMemo(() => {
    const start =
      (currentPage - 1) * ROWS_PER_PAGE;

    const end = start + ROWS_PER_PAGE;

    return data.slice(start, end);
  }, [data, currentPage]);

  return (
    <div
      style={{
        width: "100%",
        background: "#FFFFFF",
        borderRadius: 14,
        border: "1px solid #E2E8F0",
        overflow: "hidden",
      }}
    >
      {/* TABLE */}
      <div
        style={{
          width: "100%",
          overflowX: "auto",
        }}
      >
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            minWidth: 700,
          }}
        >
          {/* HEAD */}
          <thead
            style={{
              background: "#F8FAFC",
            }}
          >
            <tr>
              {columns.map((column) => {
                const isSorted =
                  sortConfig?.key === column.key;

                return (
                  <th
                    key={String(column.key)}
                    onClick={() =>
                      onSort(column.key)
                    }
                    style={{
                      padding: "16px",
                      textAlign: "left",
                      cursor: "pointer",
                      borderBottom:
                        "1px solid #E2E8F0",
                      color: "#334155",
                      fontWeight: 600,
                      fontSize: 14,
                      userSelect: "none",
                      whiteSpace: "nowrap",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 8,
                      }}
                    >
                      {column.label}

                      {isSorted && (
                        <span
                          style={{
                            fontSize: 12,
                            color: "#EA580C",
                          }}
                        >
                          {sortConfig.direction ===
                          "asc"
                            ? "▲"
                            : "▼"}
                        </span>
                      )}
                    </div>
                  </th>
                );
              })}
            </tr>
          </thead>

          {/* BODY */}
          <tbody>
            {paginatedData.map((user) => (
              <tr
                key={user.id}
                style={{
                  transition:
                    "background 0.2s ease",
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.background =
                    "#FAFAFA";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.background =
                    "#fff";
                }}
              >
                <td
                  style={{
                    padding: "16px",
                    borderBottom:
                      "1px solid #F1F5F9",
                    fontSize: 14,
                  }}
                >
                  {user.name}
                </td>

                <td
                  style={{
                    padding: "16px",
                    borderBottom:
                      "1px solid #F1F5F9",
                    fontSize: 14,
                    color: "#475569",
                  }}
                >
                  {user.email}
                </td>

                <td
                  style={{
                    padding: "16px",
                    borderBottom:
                      "1px solid #F1F5F9",
                    fontSize: 14,
                  }}
                >
                  {user.location}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* EMPTY */}
      {data.length === 0 && (
        <div
          style={{
            padding: 40,
            textAlign: "center",
            color: "#64748B",
          }}
        >
          No users found
        </div>
      )}

      {/* PAGINATION */}
      {data.length > 0 && (
        <div
          style={{
            padding: "16px 20px",
            borderTop: "1px solid #E2E8F0",
            display: "flex",
            justifyContent:
              "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            gap: 12,
          }}
        >
          <span
            style={{
              fontSize: 13,
              color: "#64748B",
            }}
          >
            Showing{" "}
            {(currentPage - 1) *
              ROWS_PER_PAGE +
              1}
            –
            {Math.min(
              currentPage * ROWS_PER_PAGE,
              data.length
            )}{" "}
            of {data.length}
          </span>

          <div
            style={{
              display: "flex",
              alignItems: "center",
              gap: 8,
            }}
          >
            <button
              disabled={currentPage === 1}
              onClick={() =>
                setCurrentPage((prev) =>
                  Math.max(prev - 1, 1)
                )
              }
              style={{
                padding: "8px 12px",
                borderRadius: 8,
                border: "1px solid #E2E8F0",
                background:
                  currentPage === 1
                    ? "#F8FAFC"
                    : "#fff",
                cursor:
                  currentPage === 1
                    ? "not-allowed"
                    : "pointer",
              }}
            >
              Prev
            </button>

            {Array.from({
              length: totalPages,
            }).map((_, index) => {
              const page = index + 1;

              const active =
                page === currentPage;

              return (
                <button
                  key={page}
                  onClick={() =>
                    setCurrentPage(page)
                  }
                  style={{
                    width: 36,
                    height: 36,
                    borderRadius: 8,
                    border: active
                      ? "none"
                      : "1px solid #E2E8F0",
                    background: active
                      ? "#EA580C"
                      : "#fff",
                    color: active
                      ? "#fff"
                      : "#0F172A",
                    fontWeight: 600,
                    cursor: "pointer",
                  }}
                >
                  {page}
                </button>
              );
            })}

            <button
              disabled={
                currentPage === totalPages
              }
              onClick={() =>
                setCurrentPage((prev) =>
                  Math.min(
                    prev + 1,
                    totalPages
                  )
                )
              }
              style={{
                padding: "8px 12px",
                borderRadius: 8,
                border: "1px solid #E2E8F0",
                background:
                  currentPage === totalPages
                    ? "#F8FAFC"
                    : "#fff",
                cursor:
                  currentPage === totalPages
                    ? "not-allowed"
                    : "pointer",
              }}
            >
              Next
            </button>
          </div>
        </div>
      )}
    </div>
  );
};
